// Canonical Expanded banking/entity inspectors. Working values stay outside the
// campaign; each accepted edit patches the latest single monthly plan.
let interfaceFinanceState={identity:null,cycle:null,forms:new Map(),accepted:new Set(),revision:0};
const financeCopy=value=>JSON.parse(JSON.stringify(value));
const financeMoney=value=>Number.isFinite(value)?overviewDollars(value):'Unavailable';
const financePrice=cents=>Number.isFinite(cents)?'$'+(cents/100).toFixed(2):'Unavailable';
function financeState(v){
 const identity=presentationCampaignIdentity(v);
 if(interfaceFinanceState.identity!==identity||interfaceFinanceState.cycle!==v.cycle)interfaceFinanceState={identity,cycle:v.cycle,forms:new Map(),accepted:new Set(),revision:interfaceFinanceState.revision+1};
 return interfaceFinanceState;
}
function financeForm(v,key,initial){
 const state=financeState(v),signature=JSON.stringify(initial);let form=state.forms.get(key);
 if(!form||!form.dirty&&form.signature!==signature){form={value:financeCopy(initial),signature,dirty:false,notice:''};state.forms.set(key,form);}
 return form;
}
function financeLeaves(value,prefix='',out={}){for(const [key,item]of Object.entries(value||{})){const path=prefix?prefix+'.'+key:key;if(item&&typeof item==='object'&&!Array.isArray(item))financeLeaves(item,path,out);else out[path]=item;}return out;}
function financeSharedForm(v,key,initial){
 const state=financeState(v);let form=state.forms.get(key);
 if(!form){form={value:financeCopy(initial),signature:JSON.stringify(initial),dirty:false,dirtyPaths:{},notice:''};state.forms.set(key,form);}
 for(const [path,value]of Object.entries(financeLeaves(initial)))if(!form.dirtyPaths[path])financeSet(form.value,path,financeCopy(value));
 form.signature=JSON.stringify(initial);return form;
}
function financeGet(object,path){return path.split('.').reduce((value,key)=>value?.[key],object);}
function financeSet(object,path,value){const keys=path.split('.'),last=keys.pop();let target=object;for(const key of keys)target=target[key]||(target[key]={});target[last]=value;}
function financeContext(route){const c=route?.context||{};return {...c,marketId:c.marketId||c.market,officeId:c.officeId||c.office};}
function financeRoute(workspace,view,context={},remember=false,focusId='financeInspectorTitle'){
 const item={workspace,view,context},moved=remember?interfaceNavigate(item,{remember:true}):openInterfaceWorkspace(workspace,view,context);if(moved===false)return;
 // Explicit navigation replaces its triggering control. Move keyboard focus to
 // the new visible destination; ordinary quote/input redraws never steal it.
 const visible=node=>node&&(!node.getClientRects||node.getClientRects().length);
 let target=$('#'+focusId);if(!visible(target))target=$('.finance-directory .finance-record[aria-current="true"]')||$('.finance-directory .finance-record');
 if(visible(target))target.focus?.({preventScroll:true});
}
function financeLock(v){return !draft||draftOwner!==v.me.id||lastCycle!==v.cycle||v.me.submitted||v.gameOver||gh.active&&gh.paused;}
function financeGuard(v){const token=interfaceToken(v),snapshot=game||view,revision=interfaceFinanceState.revision,route=typeof interfaceCurrentRoute==='function'?interfaceCurrentRoute():null;return writable=>interfaceFinanceState.revision===revision&&(game||view)===snapshot&&(!route||interfaceCurrentRoute()===route)&&interfaceCurrent(token,writable!==false);}
function financeTable(headers,rows,caption=''){return '<div class="finance-table-scroll"><table class="regional-table">'+(caption?'<caption>'+esc(caption)+'</caption>':'')+'<thead><tr>'+headers.map(x=>'<th scope="col">'+esc(x)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map((x,i)=>'<'+(i?'td':'th scope="row"')+'>'+esc(x??'Unavailable')+'</'+(i?'td':'th')+'>').join('')+'</tr>').join('')+'</tbody></table></div>';}
function financeFacts(rows){return '<dl class="finance-facts">'+rows.map(([label,value])=>'<div><dt>'+esc(label)+'</dt><dd>'+esc(value??'Unavailable')+'</dd></div>').join('')+'</dl>';}
function financeNote(text,kind=''){return '<p class="finance-note '+kind+'">'+esc(text)+'</p>';}
function financeAction(label,fn,id='financeAction',disabled=false){return {label,fn,id,disabled};}
function financeActions(mount,actions,guard){const node=mount.querySelector('.finance-actions');if(!node)return;node.innerHTML=actions.map(a=>'<button type="button" class="btn" id="'+a.id+'"'+(a.disabled?' disabled':'')+'>'+esc(a.label)+'</button>').join('');for(const action of actions)$('#'+action.id)?.addEventListener('click',()=>{if(guard(false)&&!action.disabled)action.fn();});}
function financeInspector(mount,v,{title,subtitle='',facts=[],body='',actions=[]}){
 mount.innerHTML='<section class="finance-inspector" aria-label="'+esc(title)+'"><header><h2 id="financeInspectorTitle" tabindex="-1">'+esc(title)+'</h2>'+financeNote(subtitle)+'</header>'+financeFacts(facts)+body+'<div class="finance-actions"></div><div id="financeEditorMount"></div></section>';
 financeActions(mount,actions,financeGuard(v));return $('#financeEditorMount');
}
function financeLayout(v,route,mount,records,selected,label,renderInspector){
 financeState(v);interfaceFinanceState.revision++;
 const context=financeContext(route),chosen=records.find(r=>r.id===selected)||records[0];
 const inspected=!!(context.objectId||context.productId||context.companyId||context.clientId||context.agreementId||context.opportunityId||context.inspect);
 mount.innerHTML='<div class="finance-workspace '+(inspected?'finance-inspected':'')+'"><nav class="finance-directory" aria-label="'+esc(label)+'">'+records.map((r,i)=>'<button type="button" class="finance-record" id="financeRecord'+i+'" aria-current="'+(r===chosen?'true':'false')+'"><b>'+esc(r.name)+'</b><span>'+esc(r.detail||'')+'</span></button>').join('')+'</nav><div class="finance-detail"><button class="btn finance-record-back" id="financeBackToRecords">Back to '+esc(label.toLowerCase())+'</button><div id="financeDetail"></div></div></div>';
 const guard=financeGuard(v);records.forEach((record,i)=>$('#financeRecord'+i)?.addEventListener('click',()=>{if(guard(false))financeRoute(route.workspace,route.view,{...context,objectId:record.id,...record.context});}));
 if(chosen){interfaceSetLocation?.([route.workspace==='banking'?'Banking':'Financial Group',label,chosen.name]);renderInspector(chosen,$('#financeDetail'));}
 else $('#financeDetail').innerHTML=financeNote('No objects are available in these saved rules.');
 $('#financeBackToRecords')?.addEventListener('click',()=>{if(guard(false))financeRoute(route.workspace,route.view,{},false,'financeRecord0');});
}
function financeValidate(v,candidate,{bank=true,agency=false,investment=false}={}){
 E.normalizeProductProgramPlan(v.me,candidate);if(v.me.advertising)E.normalizeAdvertisingPlan(v.me,candidate);
 if(v.me.relationshipOffers)E.normalizeRelationshipOfferPlan(v.me,candidate);if(v.me.onboarding)E.normalizeOnboardingPlan(v.me,candidate);
 if(v.me.financialGroup)E.normalizeGroupPlan(v.me,candidate);if(v.me.agency)E.normalizeAgencyPlan(v.me,candidate);
 if(v.companySharesVersion===1)E.normalizeCompanySharePlan(v,v.me,candidate);
 if(E.HoldingCapital)E.HoldingCapital.normalize(v,v.me,candidate);
 if(investment)candidate=E.investmentPlanReview(v.me,candidate,v).plan;
 let budget=null;if(bank){const status=E.projectPlanStatus(v.me,candidate,v);if(!status.eligible)throw Error(status.reason);if(v.me.companyCredit&&candidate.companyCreditOrders?.length)E.companyCreditPlanForecast(v,v.me,candidate);budget=E.planBudget(v.me,candidate,v);}
 return {candidate,budget};
}
function financeBudgetFacts(v,candidate,budget){
 if(!budget)return [];
 const protectedQuote=v.me.facilityLifecycle?E.facilityLifecycleProtectedBudget(v.me,candidate,budget,v):null;
 return [['Bank commitments',financeMoney(budget.total)],['Bank available after this plan',financeMoney(protectedQuote?.remaining??budget.discretionaryRemaining??budget.remaining)]];
}
function financeEdit(v,mount,config){
 const form=config.shared?financeSharedForm(v,config.key,config.initial):financeForm(v,config.key,config.initial),locked=financeLock(v),guard=financeGuard(v);
 if(config.bindForm)config.bindForm(form.value);
 const finish=()=>{if(!config.shared){interfaceFinanceState.forms.delete(config.key);return;}for(const field of [...config.fields,...(config.validationFields||[])])delete form.dirtyPaths[field.path];form.dirty=Object.keys(form.dirtyPaths).length>0;form.notice=form.dirty?'Other working edits are still waiting to be added.':'';};
 const controls=config.fields.map((field,index)=>{
  const id='financeField'+index,value=financeGet(form.value,field.path),label=esc(field.label);
  if(field.choices)return '<fieldset class="finance-choices"><legend>'+label+'</legend>'+field.choices.map((choice,i)=>'<button type="button" class="btn" id="'+id+'Choice'+i+'" aria-pressed="'+(String(value)===String(choice[0]))+'"'+(locked||field.disabled?' disabled':'')+'>'+esc(choice[1])+'</button>').join('')+'</fieldset>';
  return '<label class="finance-input" for="'+id+'">'+label+'<input id="'+id+'" type="'+(field.type||'number')+'" value="'+esc(value??'')+'"'+(field.min!==undefined?' min="'+field.min+'"':'')+(field.max!==undefined?' max="'+field.max+'"':'')+' step="'+(field.step||1)+'"'+(locked||field.disabled?' disabled':'')+'></label>';
 }).join('');
 mount.innerHTML='<form class="finance-form" onsubmit="return false"><div class="finance-fields">'+controls+'</div><div id="financeQuote" class="finance-quote" aria-live="polite"></div><div class="finance-form-actions"><button type="button" class="btn primary" id="financeStage"'+(locked?' disabled':'')+'>'+esc(config.stageLabel||((config.planned||interfaceFinanceState.accepted.has(config.key))?'Update planned action':'Add to monthly plan'))+'</button><button type="button" class="btn" id="financeDiscard">Discard working edits</button>'+(config.remove?'<button type="button" class="btn" id="financeRemove"'+(locked?' disabled':'')+'>'+esc(config.removeLabel||'Remove planned action')+'</button>':'')+'</div><p id="financeFormStatus" role="status">'+esc(form.notice||'Working edits stay here until added to your monthly plan.')+'</p></form>';
 const prepare=()=>{const now=currentView();if(!guard(false))throw Error('The bank, month, plan or connection changed. Reopen this editor.');const values=financeCopy(form.value);for(const field of [...config.fields,...(config.validationFields||[])]){if(field.choices||field.type==='text')continue;const raw=financeGet(values,field.path);if(String(raw??'').trim()===''||!Number.isFinite(Number(raw)))throw Error(field.label+' requires a number.');const number=Number(raw);if(field.min!==undefined&&number<field.min||field.max!==undefined&&number>field.max)throw Error(field.label+' is outside its supported range.');if((field.step??1)===1&&!Number.isSafeInteger(number))throw Error(field.label+' requires a whole number.');financeSet(values,field.path,number);}const result=config.build(now,values,financeCopy(draft));if(!result?.candidate)throw Error('This action could not be quoted.');return result;};
 const quote=()=>{try{const result=prepare();$('#financeQuote').innerHTML=financeFacts(result.facts||financeBudgetFacts(currentView(),result.candidate,result.budget))+(result.notes||[]).map(n=>financeNote(n)).join('');$('#financeStage').disabled=locked||result.blocked===true;return result;}catch(error){$('#financeQuote').innerHTML=financeNote('Unavailable: '+error.message,'bad');$('#financeStage').disabled=true;return null;}};
 const changed=(field,value)=>{if(!guard())return;financeSet(form.value,field.path,value);form.dirty=true;form.route=financeCopy(interfaceCurrentRoute());form.title=$('#financeInspectorTitle')?.textContent||field.label;form.editRoutes={...(form.editRoutes||{}),[field.path]:{route:form.route,title:form.title}};if(config.shared)form.dirtyPaths[field.path]=true;form.notice='Working changes have not been added to the monthly plan.';$('#financeFormStatus').textContent=form.notice;quote();};
 config.fields.forEach((field,index)=>{const id='financeField'+index;if(field.choices)field.choices.forEach((choice,i)=>$('#'+id+'Choice'+i)?.addEventListener('click',()=>{changed(field,choice[0]);field.choices.forEach((_,j)=>$('#'+id+'Choice'+j)?.setAttribute('aria-pressed',String(i===j)));}));else $('#'+id)?.addEventListener('input',e=>changed(field,e.target.value));});
 $('#financeStage')?.addEventListener('click',()=>{if(!guard())return;try{const result=prepare();if(result.blocked)return;if(config.reviewAction){config.reviewAction(currentView());return;}const before=financeCopy(draft);draft=result.candidate;interfaceFinanceState.accepted.add(config.key);finish();if(config.accepted)config.accepted(before,draft);renderReady(currentView());toast('Added to your monthly plan.');}catch(error){$('#financeFormStatus').textContent=error.message;quote();}});
 $('#financeDiscard')?.addEventListener('click',()=>{if(!guard(false))return;finish();renderReady(currentView());});
 $('#financeRemove')?.addEventListener('click',()=>{if(!guard())return;try{const candidate=config.remove(currentView(),financeCopy(draft));draft=candidate;interfaceFinanceState.forms.delete(config.key);renderReady(currentView());toast('Planned instruction removed.');}catch(error){$('#financeFormStatus').textContent=error.message;}});
 quote();return form;
}
function pendingInterfaceFinanceEdits(v){
 const state=financeState(v),rows=[],seen=new Set();for(const form of state.forms.values()){if(!form.dirty)continue;const routes=form.dirtyPaths?Object.keys(form.dirtyPaths).map(path=>form.editRoutes?.[path]).filter(Boolean):[{route:form.route,title:form.title}];for(const entry of routes){if(!entry.route)continue;const key=JSON.stringify(entry.route);if(seen.has(key))continue;seen.add(key);rows.push({title:entry.title||'Banking / Group working edits',text:'Working values have not been added to the monthly plan.',...financeCopy(entry.route)});}}return rows;
}
function financeChoices(table){return Object.entries(table).map(([key,row])=>[key,row.name||row.label||key]);}
function financeRouteAction(label,workspace,view,context={},id){return financeAction(label,()=>financeRoute(workspace,view,context,true),id);}
function financeMarketPicker(v,mount,c){const selected=v.territories[c.marketId]?c.marketId:draft.focus,rows=Object.entries(v.territories),guard=financeGuard(v);mount.insertAdjacentHTML('beforebegin','<div class="finance-option-list" aria-label="Inspected market">'+rows.map(([id,t],i)=>'<button class="btn" id="financeMarket'+i+'" aria-pressed="'+(id===selected)+'">'+esc(t.name)+'</button>').join('')+'</div>');rows.forEach(([id],i)=>$('#financeMarket'+i).onclick=()=>{if(guard(false)){const route=interfaceCurrentRoute();financeRoute(route.workspace,route.view,{...route.context,marketId:id});}});return selected;}
function financeProject(v,mount,key,{marketId}={}){
 const definition=v.projects[key],target=v.financialGroupVersion===10&&definition?.target?marketId||draft.focus:draft.focus,terms=E.projectStartTerms(v,v.me,key,target);
 if(!definition){mount.innerHTML=financeNote('This project is not supported in these saved rules.');return;}
 const planned=E.planInitiatives(draft).includes(key);
 if(definition.target){const markets=Object.entries(v.territories),guard=financeGuard(v);mount.insertAdjacentHTML('beforebegin',v.financialGroupVersion===10?'<p class="small">Project target · '+esc(v.territories[target].name)+'</p><div class="finance-option-list">'+markets.map(([id,t],i)=>'<button class="btn" id="financeProjectTarget'+i+'" aria-pressed="'+(id===target)+'">'+esc(t.name)+'</button>').join('')+'</div>':financeNote('This saved ruleset uses monthly focus: '+v.territories[target].name+'. Inspecting another market does not retarget this project.'));if(v.financialGroupVersion===10)markets.forEach(([id],i)=>$('#financeProjectTarget'+i).onclick=()=>{if(guard(false)){const route=interfaceCurrentRoute();financeRoute(route.workspace,route.view,{...route.context,marketId:id});}});}
 financeEdit(v,mount,{key:'project:'+key,initial:{include:planned},planned,stageLabel:(planned?'Update planned ':'Add project: ')+definition.name,removeLabel:'Remove '+definition.name+' from plan',fields:[],build:(now,_,candidate)=>{
  let result=!E.planInitiatives(candidate).includes(key)&&typeof initiativeCandidate==='function'?initiativeCandidate(now,key,candidate,target):null;
  if(result&&!result.status.eligible)throw Error(result.status.reason);
  if(result?.candidate)candidate=result.candidate;else{candidate.newProjects=[...new Set([...E.planInitiatives(candidate),key])];candidate.newProject=candidate.newProjects[0]||null;if(definition.target&&now.financialGroupVersion===10)candidate.projectTargets={...(candidate.projectTargets||{}),[key]:target};}
  const reviewed=financeValidate(now,candidate);return {...reviewed,facts:[['Initial commitment',financeMoney(terms.cost)],['Delivery work',terms.cycles+' months at full delivery'],['Shared execution needed',definition.capacity],...financeBudgetFacts(now,candidate,reviewed.budget)],notes:[definition.desc,'Work is not a guaranteed calendar completion date. Availability and shared delivery capacity are rechecked at settlement.']};
 },remove:planned?(now,candidate)=>{candidate.newProjects=E.planInitiatives(candidate).filter(id=>id!==key);candidate.newProject=candidate.newProjects[0]||null;if(candidate.projectTargets)delete candidate.projectTargets[key];return candidate;}:null});
}
function renderInterfaceBanking(v,route,mount){
 const viewKey=({relationships:'services',business:'services',portfolio:'lending',pricing:'deposits',policies:'treasury'})[route.view]||route.view||'deposits';route={...route,workspace:'banking',view:viewKey};
 mount=financeWorkspaceFrame(v,route,mount,'Banking',[['deposits','Deposits'],['lending','Lending'],['services','Business services'],...(v.partnerCardsVersion===1?[['cards','Cards']]:[]),['treasury','Treasury']]);
 if(viewKey==='deposits')return renderFinanceDeposits(v,route,mount);
 if(viewKey==='lending')return renderFinanceLending(v,route,mount);
 if(viewKey==='services')return renderFinanceServices(v,route,mount);
 if(viewKey==='cards'&&v.partnerCardsVersion===1)return renderPartnerCards(v,route,mount);
 return renderFinanceTreasury(v,route,mount);
}
function financeWorkspaceFrame(v,route,mount,title,views){
 financeState(v);mount.innerHTML='<header class="finance-heading"><div><p class="eyebrow">'+esc(title)+'</p><h1>'+esc(views.find(x=>x[0]===route.view)?.[1]||title)+'</h1></div><p class="small muted">One shared monthly plan. Working edits are added only when you choose Add or Update.</p></header><nav class="finance-view-nav" aria-label="'+esc(title)+' views">'+views.map(([key,label],i)=>'<button class="btn" id="financeView'+i+'" aria-current="'+(route.view===key?'page':'false')+'">'+esc(label)+'</button>').join('')+'</nav><div id="financeWorkspaceContent"></div>';
 const token=interfaceToken(v),active=interfaceCurrentRoute();views.forEach(([key],i)=>$('#financeView'+i).addEventListener('click',()=>{if(interfaceCurrent(token,false)&&interfaceCurrentRoute()===active)financeRoute(route.workspace,key,{});}));return $('#financeWorkspaceContent');
}
function renderFinanceDeposits(v,route,mount){
 const c=financeContext(route),records=Object.entries(v.productPortfolios.retail.options).map(([id,p])=>({id,name:p.name,detail:v.me.productPrograms?.products[id]?.retired?'Servicing retained accounts':'Product terms and delivery',context:{productId:id,mode:null}}));
 records.push({id:'base',name:'Base deposit pricing',detail:'Bank-wide funding mandate'},{id:'term',name:'Term deposits',detail:'Subscriptions and maturities'});
 if(v.me.householdBook)records.push({id:'households',name:'Household relationships',detail:'Retention and segment priorities'});
 if(v.me.relationshipOffers)records.push({id:'offers',name:'Relationship offers',detail:'Target existing prospects'});
 if(v.me.relationshipOffers)records.push({id:'effects',name:'Compare customer effects',detail:'Offer and staffing tradeoffs'});
 if(v.me.onboarding)records.push({id:'applications',name:'Account applications',detail:'Onboarding and pending batches'});
 for(const o of v.opportunities.filter(o=>financeOpportunityRoute(v,o.id)?.view==='deposits'))records.push({id:'opportunity:'+o.id,name:o.name,detail:'Household deposit opportunity',context:{opportunityId:o.id}});
 financeLayout(v,route,mount,records,c.opportunityId?'opportunity:'+c.opportunityId:c.objectId||c.productId,'Deposits',(record,detail)=>{
  const id=record.id,product=v.productPortfolios.retail.options[id];
  if(id.startsWith('opportunity:'))return financeOpportunity(v,financeInspector(detail,v,{title:record.name,subtitle:record.detail}),id.slice(12));
  if(product){
   const price=E.productPricingQuote(v.me,v,draft),row=price.rows[id],mode=c.mode||'terms';
   const editor=financeInspector(detail,v,{title:product.name,subtitle:product.desc,facts:[['Variable balances',financeMoney(row.variable)],['Protected balances',financeMoney(row.protected)],['Quoted annual rate',(row.rate*12/10000).toFixed(3)+'%'],['Monthly direct funding cost',financeMoney(row.directCost)]],actions:[
    financeAction('Edit pricing',()=>financeRoute('banking','deposits',{...c,objectId:id,productId:id,mode:'terms'}),'depositTerms'),
    financeAction('Delivery & licensing',()=>financeRoute('banking','deposits',{...c,objectId:id,productId:id,mode:'delivery'}),'depositDelivery'),
    financeAction('Local sales',()=>financeRoute('banking','deposits',{...c,objectId:id,productId:id,mode:'sales'}),'depositSales'),
    financeAction('Compare current price plan',()=>financeRoute('banking','deposits',{...c,objectId:id,productId:id,mode:'comparison'}),'depositComparison'),
    financeRouteAction('Base pricing','banking','deposits',{objectId:'base'},'depositBase')
   ]});
   if(mode==='delivery')return financeDepositDelivery(v,editor,id,c);
   if(mode==='sales')return financeDepositSales(v,editor,id,c);
   if(mode==='comparison')return financePriceComparison(v,editor);
   if(row.bp===null||!row.editable){editor.innerHTML=financeNote(row.bp===null?'This savings product uses its automatic guarantee quote. Existing guarantees keep their terms.':'Develop or license this product before changing its terms. Existing accounts retain their stamped promises.');return;}
   financeEdit(v,editor,{key:'deposit-price:'+id,initial:{bp:draft.productProgramPolicy.pricingBp[id]},fields:[{path:'bp',label:'Annual adjustment to base pricing',choices:[[-25,'−0.25 percentage points'],[0,'Base tariff'],[25,'+0.25 percentage points']]}],build:(now,f,candidate)=>{candidate.productProgramPolicy.pricingBp[id]=f.bp;const checked=financeValidate(now,candidate),q=E.productPricingQuote(now.me,now,candidate).rows[id];return {...checked,facts:[['Proposed annual rate',(q.rate*12/10000).toFixed(3)+'%'],['Monthly interest',financeMoney(q.interest)],['Service/platform',financeMoney(q.service)],['Customer fees',financeMoney(q.fees)],['Direct funding cost',financeMoney(q.directCost)]],notes:['Variable accounts reprice; guarantees and locked terms keep their stamped promises. Direct funding cost is not total product profit.']};}});return;
  }
  const editor=financeInspector(detail,v,{title:record.name,subtitle:record.detail});
  if(id==='base')return financeEdit(v,editor,{key:'deposit-base',initial:{policy:draft.depositPolicy},fields:[{path:'policy',label:'Deposit mandate',choices:financeChoices(v.depositPolicies)}],build:(now,f,candidate)=>{candidate.depositPolicy=f.policy;return financeValidate(now,candidate);}});
  if(id==='term'){
   if(!v.me.termFunding){editor.innerHTML=financeNote('Locked term deposits are not enabled in these saved rules.');return;}
   const q=E.termSummary(v.me);editor.insertAdjacentHTML('beforebegin',financeFacts([['Locked principal',financeMoney(q.locked)],['Maturing next operations',financeMoney(q.maturing)],['Current monthly interest',financeMoney(q.interest)]]));
   return financeEdit(v,editor,{key:'deposit-term',initial:financeCopy(draft.termPolicy),fields:[{path:'offer',label:'New subscriptions',choices:[['off','Closed'],['six','Offer six-month deposits']]},{path:'maturity',label:'At maturity',choices:[['release','Release to current savings'],['renew','Renew at then-current quote']]}],build:(now,f,candidate)=>{candidate.termPolicy=f;return {...financeValidate(now,candidate),notes:['Closing subscriptions does not cancel existing terms. Renewal uses the then-current quote; obligations to departing customers still apply.']};}});
  }
  if(id==='households')return financeHouseholds(v,editor,c);
  if(id==='effects')return financeCustomerEffects(v,editor);
  return financeCustomerPolicy(v,editor,id==='offers'?'relationshipOfferPolicy':'onboardingPolicy',c);
 });
}
